import {exercises,checkAnswer} from '../exercises.js';
import {exercisePanel} from './guidance.js';
import {lessons,recipes,workflows,commands,sources} from '../content.js';
import {e,sourceLink,command,breadcrumb,pageHead,lessonCard,problemCard,workflowCard,notFound} from '../ui.js';
import {scenarios,getScenario} from '../model.js';
export function learn({completed=[]}={}){return pageHead('LEARN / THE ESSENTIALS','Make Terraform make sense.','Eight short lessons to build a working mental model. Start at the beginning or jump to the idea you need.')+`<div class="callout"><strong>Your learning path</strong><div class="progress-track"><div class="progress-fill" style="width:${completed.length/lessons.length*100}%"></div></div><span class="small">${completed.length} of ${lessons.length} lessons marked complete · Progress is stored only in this browser.</span></div><div class="cards">${lessons.map(l=>lessonCard(l,completed)).join('')}</div>`;}

export function lesson(id,{completed=[],answers={}}={}){
 const l=lessons.find(x=>x.id===id);if(!l)return notFound();
 const next=lessons[l.number];
 return breadcrumb('learn','Learn')+pageHead(`LESSON ${String(l.number).padStart(2,'0')} / ${e(l.time)}`,e(l.title),e(l.summary))+`<div class="article-layout"><article class="article"><h2>The plain-English version</h2><p>${e(l.explanation)}</p><div class="callout"><strong>More precisely</strong><p>${e(l.definition)}</p></div><h2>${e(l.exampleTitle)}</h2>${command(l.example,l.exampleNote,l.id==='desired-state'||l.id==='resources-providers'||l.id==='variables-values'?'HCL example':'Illustrative example')}<h2>A common misconception</h2><p>${e(l.misconception)}</p>${l.simulation?simulator():''}<details class="advanced-only"><summary>A closer look</summary><p>${e(l.advanced)}</p></details><h2>Try this next</h2><p>${e(l.next)}</p>${l.link?`<a class="button small" href="#${l.link}">Open the related guide →</a>`:''}${exercisePanel(l.id,answers[l.id])}<div class="lesson-next"><button class="button primary" data-complete="${l.id}" ${!completed.includes(l.id)&&!(answers[l.id]?.checked&&checkAnswer(l.id,answers[l.id]?.value)?.correct)?'disabled':''}>${completed.includes(l.id)?'✓ Marked complete':'Mark lesson complete'}</button>${next?`<a class="button" href="#lesson/${next.id}">Next: ${e(next.title)} →</a>`:'<a class="button" href="#workflow/start">Try the local practice project →</a>'}</div></article><aside class="aside"><div class="aside-inner"><h3>In this lesson</h3><p>${e(l.label)} · ${e(l.time)}</p><p>${e(l.version)}</p>${sourceLink(l.source)}<hr class="section-divider"><h3>Learning path</h3>${lessons.map(x=>`<a href="#lesson/${x.id}" ${x.id===l.id?'aria-current="page"':''}>${completed.includes(x.id)?'✓':String(x.number).padStart(2,'0')} · ${e(x.title)}</a>`).join('')}<p>Source reviewed ${l.reviewed}. Examples have not been executed against cloud services.</p><button class="button small" data-share>Copy lesson link</button></div></aside></div>`;
}

export function simulator(){return `<section class="simulator" aria-labelledby="sim-heading"><span class="pill">SIMULATION · NO COMMANDS RUN</span><h3 id="sim-heading" style="margin-top:15px">Change one thing. See the proposal.</h3><p>Select a scenario to compare configuration, recorded bindings and current objects.</p><div class="sim-buttons" role="group" aria-label="Simulation scenario">${Object.entries(scenarios).map(([id,s])=>`<button data-scenario="${id}" aria-pressed="${id==='aligned'}">${e(s.label)}</button>`).join('')}</div><div id="sim-output" aria-live="polite">${simulationOutput('aligned')}</div></section>`;}

export function simulationOutput(id){const s=getScenario(id);return `<div class="sim-zones"><div class="sim-zone"><b>Configuration</b><code>${e(s.configuration)}</code></div><div class="sim-zone"><b>Recorded binding</b><code>${e(s.recorded)}</code></div><div class="sim-zone"><b>Actual object</b><code>${e(s.actual)}</code></div></div>${command(s.plan,'Simulated proposal','Plan fixture')}<strong class="small">${e(s.summary)}</strong><p style="margin-top:12px">${e(s.reason)}</p><p class="small muted">Fictional provider behaviour for teaching. This is not a prediction for a real resource.</p>`;}
